import{_ as l,a0 as o,w as r,s as p,I as s,x as n,a1 as a,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"将应用程序迁移到容器的 5 个步骤 | LCTT x X-CMD","titleTemplate":false,"description":"将应用程序迁移到容器的 5 个步骤 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将应用程序迁移到容器的 5 个步骤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将应用程序迁移到容器的 5 个步骤 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220208 5 steps to migrate your application to containers","title":"将应用程序迁移到容器的 5 个步骤","tag":"202202","desc":""},"relativePath":"202202/20220208 5 steps to migrate your application to containers.md","filePath":"[post].md"}'),u={name:"202202/20220208 5 steps to migrate your application to containers.md"};function m(f,t,g,b,k,x){const i=o("Link");return r(),p("div",null,[t[29]||(t[29]=s("h1",{id:"将应用程序迁移到容器的-5-个步骤",tabindex:"-1"},[n("将应用程序迁移到容器的 5 个步骤 "),s("a",{class:"header-anchor",href:"#将应用程序迁移到容器的-5-个步骤","aria-label":"Permalink to “将应用程序迁移到容器的 5 个步骤”"},"​")],-1)),t[30]||(t[30]=s("blockquote",null,[s("p",null,"如果你是容器的新手，不要被那些术语所吓倒。这些关键原则将帮助你把应用迁移到云中。")],-1)),t[31]||(t[31]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202202/14/224455i7wz95yiq9hxltw2.jpg",alt:""})],-1)),s("p",null,[t[1]||(t[1]=n("一般来说，人们想使用你的应用程序这是一件好事。然而，当应用程序在服务器上运行时，应用程序受欢迎是有代价的。随着用户对资源需求的增加，在某些时候，你可能会发现你需要扩展你的应用程序。一种选择是在这种情况下增加更多的服务器，建立一个像 Nginx 这样的 ",-1)),a(i,{href:"https://opensource.com/article/21/4/load-balancing"},{default:e(()=>[...t[0]||(t[0]=[n("负载平衡器",-1)])]),_:1}),t[2]||(t[2]=n("，以满足需求。但是，这种方法的成本可能很昂贵，因为当需求低的时候，在没有流量的服务器上运行你的应用程序的实例并不会节省资源。容器的优点是它是非持久的，在有需求时启动新实例，而随着需求的减少逐渐消失。如果这听起来像是你需要的功能，那么现在可能是将你的应用程序迁移到容器的时候了。",-1))]),t[32]||(t[32]=d(`<p>将应用程序迁移到容器中，很快就会变得迷失方向。虽然容器内的环境可能感觉很熟悉，但许多容器镜像是最小化的，而且它们被设计为无状态的。不过在某种程度上，这也是容器的优势之一。就像 Python 虚拟环境一样，它是一块白板，可以让你构建（或重建）你的应用程序，而没有许多其他环境所提供的无形的默认值。</p><p>每一次向云服务的迁移都是独一无二的，但在将你的应用程序移植到容器之前，你应该注意以下几个重要原则。</p><h3 id="_1、理解你的依赖关系" tabindex="-1">1、理解你的依赖关系 <a class="header-anchor" href="#_1、理解你的依赖关系" aria-label="Permalink to “1、理解你的依赖关系”">​</a></h3><p>将你的应用程序移植到容器中是一个很好的机会，可以了解你的应用程序实际依赖的东西。由于除了最基本的系统组件外，很少有默认安装的组件，你的应用程序一开始不太可能在容器中运行。</p><p>在重构之前，确定你的依赖关系。首先，在你的源代码中用 <code>grep</code> 查找 <code>include</code>、<code>import</code>、<code>require</code>、<code>use</code> 或你选择的语言中用来声明依赖关系的任何关键词。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~/Code/myproject -type f \\</span></span>
<span class="line"><span>    -iname &quot;.java&quot; \\</span></span>
<span class="line"><span>    -exec grep import {} \\;</span></span></code></pre></div><p>不过，仅仅识别你使用的特定语言的库可能是不够的。审计依赖关系，这样你就能知道是否有语言本身运行所需的低级库，或者特定的模块以预期的功能运行。</p><h3 id="_2、评估你的数据存储" tabindex="-1">2、评估你的数据存储 <a class="header-anchor" href="#_2、评估你的数据存储" aria-label="Permalink to “2、评估你的数据存储”">​</a></h3><p>容器是无状态的，当一个容器崩溃或停止运行时，该容器的实例就永远消失了。如果你要在该容器中保存数据，这些数据也会消失。如果你的应用程序存储用户数据，所有的存储必须发生在容器之外，在你的应用程序的实例可以访问的某个位置。</p><p>你可以使用映射到容器内某个位置的本地存储来存储简单的应用程序配置文件。这是一种常见的技术，适用于需要管理员提供简单配置值的 Web 应用程序，如管理员的电子邮件地址、网站标题等。比如说：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman run \\</span></span>
<span class="line"><span>    --volume /local/data:/storage:Z \\</span></span>
<span class="line"><span>    mycontainer</span></span></code></pre></div>`,11)),s("p",null,[t[4]||(t[4]=n("然而，你可以配置一个数据库，如 MariaDB 或 PostgreSQL，将大量数据在几个容器中的共享存储。对于私人信息，如密码，",-1)),a(i,{href:"https://www.redhat.com/sysadmin/new-podman-secrets-command"},{default:e(()=>[...t[3]||(t[3]=[n("你可以配置一个机密存储",-1)])]),_:1}),t[5]||(t[5]=n("。",-1))]),t[33]||(t[33]=s("p",null,"对于你需要如何重构你的代码，相应地调整存储位置，这可能意味着改变路径到新的容器存储映射，移植到不同的数据库，甚至是纳入容器特定的模块。",-1)),t[34]||(t[34]=s("h3",{id:"_3、准备好你的-git-仓库",tabindex:"-1"},[n("3、准备好你的 Git 仓库 "),s("a",{class:"header-anchor",href:"#_3、准备好你的-git-仓库","aria-label":"Permalink to “3、准备好你的 Git 仓库”"},"​")],-1)),s("p",null,[t[7]||(t[7]=n("容器在构建时通常会从 Git 仓库中拉取源代码。一旦你的 Git 仓库成为你的应用程序的生产就绪代码的标准来源，你必须有一个管理 Git 仓库的计划。要有一个发布分支或生产分支，并考虑使用 ",-1)),a(i,{href:"http://redhat.com/sysadmin/git-hooks"},{default:e(()=>[...t[6]||(t[6]=[n("Git 钩子",-1)])]),_:1}),t[8]||(t[8]=n(" 来拒绝意外的未经批准的提交。",-1))]),t[35]||(t[35]=s("h3",{id:"_4、了解你的构建系统",tabindex:"-1"},[n("4、了解你的构建系统 "),s("a",{class:"header-anchor",href:"#_4、了解你的构建系统","aria-label":"Permalink to “4、了解你的构建系统”"},"​")],-1)),t[36]||(t[36]=s("p",null,"容器化应用程序可能没有传统的发布周期。当容器被构建时，它们会被从 Git 中拉取出来。你可以启动任何数量的构建系统作为容器构建的一部分，但这可能意味着调整你的构建系统，使其比过去更加自动化。你应该重构你的构建过程，使你完全有信心它能在无人值守的情况下工作。",-1)),t[37]||(t[37]=s("h3",{id:"_5、构建镜像",tabindex:"-1"},[n("5、构建镜像 "),s("a",{class:"header-anchor",href:"#_5、构建镜像","aria-label":"Permalink to “5、构建镜像”"},"​")],-1)),s("p",null,[t[11]||(t[11]=n("构建镜像不一定是复杂的任务。你可以使用 ",-1)),a(i,{href:"https://www.redhat.com/sysadmin/top-container-images"},{default:e(()=>[...t[9]||(t[9]=[n("现有的容器镜像",-1)])]),_:1}),t[12]||(t[12]=n(" 作为基础，用一个简单的 Docker 文件对其进行调整。另外，你也可以使用 ",-1)),a(i,{href:"https://opensource.com/article/22/1/build-your-own-container-scratch"},{default:e(()=>[...t[10]||(t[10]=[n("Buildah",-1)])]),_:1}),t[13]||(t[13]=n(" 从头开始构建你自己的镜像。",-1))]),t[38]||(t[38]=s("p",null,"在某种程度上，构建容器的过程与实际重构代码一样，都是开发的一部分。容器的构建是为了获取、组装和执行你的应用程序，所以这个过程必须是自动化的、健壮的。建立一个好的镜像，就为你的应用程序建立了一个坚实可靠的基础。",-1)),t[39]||(t[39]=s("h3",{id:"容器化",tabindex:"-1"},[n("容器化 "),s("a",{class:"header-anchor",href:"#容器化","aria-label":"Permalink to “容器化”"},"​")],-1)),t[40]||(t[40]=s("p",null,"如果你是容器的新手，不要被这些术语所吓倒。容器只是另一种环境。容器化开发的感知约束实际上可以帮助你专注于你的应用程序，并更好地了解它是如何运行的、它需要什么才能可靠地运行，以及当出错时有哪些潜在的风险。相反，这导致系统管理员在安装和运行你的应用程序时受到的限制要少得多，因为从本质上讲，容器是一个受控的环境。仔细审查你的代码，了解你的应用程序需要什么，并相应地重构它。",-1)),t[41]||(t[41]=s("hr",null,null,-1)),s("p",null,[t[15]||(t[15]=n("via: ",-1)),a(i,{href:"https://opensource.com/article/22/2/migrate-application-containers"},{default:e(()=>[...t[14]||(t[14]=[n("https://opensource.com/article/22/2/migrate-application-containers",-1)])]),_:1})]),s("p",null,[t[20]||(t[20]=n("作者：",-1)),a(i,{href:"https://opensource.com/users/alansmithee"},{default:e(()=>[...t[16]||(t[16]=[n("Alan Smithee",-1)])]),_:1}),t[21]||(t[21]=n(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[17]||(t[17]=[n("lujun9972",-1)])]),_:1}),t[22]||(t[22]=n(" 译者：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[18]||(t[18]=[n("wxy",-1)])]),_:1}),t[23]||(t[23]=n(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[19]||(t[19]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[26]||(t[26]=n("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[24]||(t[24]=[n("LCTT",-1)])]),_:1}),t[27]||(t[27]=n(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...t[25]||(t[25]=[n("Linux中国",-1)])]),_:1}),t[28]||(t[28]=n(" 荣誉推出",-1))])])}const h=l(u,[["render",m]]);export{C as __pageData,h as default};
